"""Camada didática do bloco “Problemas sociais do Brasil”: META (temas, quiz de aplicação), REFORCO (analogia, criança),
DID_BR (objetivos, pontos para guardar, pergunta para pensar, pré-requisitos) e DID2_BR (caso, erro comum, ferramenta, duas perguntas)."""

META_BR = {
 'dividas-e-devedores': (['economia', 'brasil'], ('Uma empresa sabe que, a cada poucos anos, o governo abre um novo Refis com perdão de multas e juros. O que a lição prevê sobre o comportamento dela?', ['Que ela pagará em dia para evitar multas', 'Que tende a atrasar impostos esperando o próximo programa, porque o perdão recorrente premia o atraso', 'Que o Refis não muda nada'], 1, 'Perdão genérico e recorrente cria o incentivo que diz combater; a transação caso a caso tenta corrigir isso.')),
 'impunidade': (['perigos', 'brasil'], ('Um governador propõe dobrar todas as penas de roubo e não muda nada na polícia civil, que esclarece poucos casos. O que a evidência sobre dissuasão prevê?', ['Queda forte do crime', 'Efeito pequeno: a chance de ser pego pesa mais do que o tamanho da pena', 'Aumento do crime'], 1, 'Certeza da punição dissuade mais do que severidade; sem investigação, pena alta é promessa vazia.')),
 'os-protegidos': (['democracia', 'brasil'], ('Um empresário sonega R$ 10 milhões e, quando descoberto, paga o imposto. O que acontece com a punição criminal?', ['Ele é preso de qualquer forma', 'O pagamento extingue a punição criminal, uma regra que crimes comuns não têm', 'Ele perde o CNPJ'], 1, 'É um dos exemplos de como a lei trata diferente crimes de quem tem dinheiro.')),
 'golpes-e-fraudes': (['desinformacao', 'brasil'], ('Você recebe uma ligação do “banco” dizendo que sua conta foi invadida e que é preciso transferir o saldo para uma conta segura. O que fazer?', ['Transferir rápido para proteger o dinheiro', 'Desligar e ligar você mesmo para o número oficial do banco; banco não pede transferência', 'Passar os dados para confirmar a identidade'], 1, 'Urgência e medo são as ferramentas do golpe; a defesa é interromper e checar pelo canal oficial.')),
 'transparencia-dos-gastos': (['democracia', 'brasil'], ('Você quer saber quanto a prefeitura pagou pela reforma da escola do bairro, e o portal não mostra. O que a Lei de Acesso garante?', ['Nada, se o prefeito não quiser', 'Que você pode pedir a informação sem justificar, e o órgão deve responder em até 20 dias, prorrogáveis por mais 10', 'Que só jornalistas podem pedir'], 1, 'A LAI vale para qualquer pessoa e para todos os níveis de governo.')),
 'faccoes-e-sistema-prisional': (['perigos', 'brasil'], ('Uma cidade prende mil jovens por vender pequenas quantidades de droga. O tráfico local diminui?', ['Sim, pela metade', 'Pouco: os varejistas são substituídos, e a prisão superlotada aumenta o recrutamento da facção', 'Acaba'], 1, 'Atacar o dinheiro e retomar as prisões desorganiza mais do que prender o varejo.')),
 'milicias': (['perigos', 'brasil'], ('Num bairro, um grupo de policiais de folga cobra “taxa de segurança”, vende gás e internet e apoia um candidato a vereador. Isso é…', ['Policiamento comunitário', 'Milícia: controle armado de território, serviços e votos por agentes ligados ao Estado', 'Empreendedorismo'], 1, 'A marca da milícia é usar a condição de agente do Estado para explorar o território.')),
 'desigualdade-social': (['economia', 'brasil'], ('Qual destas medidas tem evidência mais forte de ter reduzido a pobreza extrema no Brasil?', ['Isentar dividendos', 'Transferências focalizadas, como o Bolsa Família, e a valorização do salário mínimo', 'Aumentar impostos sobre consumo'], 1, 'Os estudos do Ipea apontam efeito grande e custo relativamente baixo.')),
 'bets': (['economia', 'mente'], ('A maior parte do lucro de uma casa de apostas vem de quem?', ['De quem aposta pouco e por diversão', 'De uma minoria que aposta muito e perde muito, muitas vezes com sinais de vício', 'Dos patrocínios'], 1, 'Por isso a regulação forte mira limites de gasto, pausa e autoexclusão.')),
}

REFORCO_BR = {
 'dividas-e-devedores': dict(analogia='Numa república de estudantes, um morador sempre atrasa a conta de luz, e todo fim de ano os outros perdoam e dividem o que ele devia. Quem paga em dia começa a se perguntar por que paga. Perdoar quem perdeu o emprego é solidariedade; perdoar todo ano quem pode pagar é ensinar todos a atrasar.', crianca='Se você esquece de devolver um livro e a biblioteca perdoa uma vez, tudo bem, todo mundo erra. Mas se ela perdoa sempre, ninguém mais devolve no prazo. Regras boas ajudam quem teve um problema de verdade e cobram quem só não quis.'),
 'impunidade': dict(analogia='Num jogo de futebol em que o juiz quase nunca vê a falta, aumentar o tamanho do cartão não adianta: o jogador sabe que não vai ser pego. O que muda o jogo é ter juiz olhando. Na segurança pública é igual: a chance de ser pego pesa mais que o tamanho da pena.', crianca='Se na escola ninguém descobre quem riscou a parede, não adianta prometer um castigo enorme. O que faz as pessoas pararem é saber que alguém vai descobrir. Por isso investigar bem é mais importante do que gritar castigos.'),
 'os-protegidos': dict(analogia='Imagine uma corrida em que alguns corredores podem pedir para o juiz recomeçar a largada quantas vezes quiserem, enquanto os outros correm uma vez só. A regra é a mesma para todos no papel, mas quem pode recomeçar sempre chega ao fim do tempo sem perder. É assim que o tempo vira defesa para quem pode pagar.', crianca='Se uma regra da sala vale para todos, mas o filho da diretora sempre consegue um jeito de não cumprir, os outros sentem que a regra não é de verdade. Justiça é a mesma regra valer igual para todo mundo.'),
 'golpes-e-fraudes': dict(analogia='Um ladrão que leva sua carteira e sai correndo por um labirinto de cem portas, enquanto quem o persegue precisa de autorização para abrir cada uma. O Pix é o labirinto rápido; o golpe vence porque a investigação abre as portas devagar.', crianca='Às vezes alguém finge ser outra pessoa para pedir dinheiro, como um lobo fantasiado de vovó. A regra é: se alguém pede dinheiro com pressa, pare e pergunte para um adulto de confiança, pelo telefone que vocês já conhecem.'),
 'transparencia-dos-gastos': dict(analogia='Num condomínio, o síndico mostra a planilha de gastos todo mês, com nota fiscal. Ninguém precisa desconfiar dele para conferir; conferir é o que mantém todo mundo honesto. Um síndico que esconde a planilha pode até ser honesto, mas ninguém tem como saber.', crianca='Se a turma junta dinheiro para uma festa, todo mundo quer saber quanto foi gasto em cada coisa. Mostrar a conta não é desconfiar, é combinar. Com o dinheiro do país é igual: é de todo mundo, então todo mundo pode ver.'),
 'faccoes-e-sistema-prisional': dict(analogia='Um hospital tão lotado e sujo que as pessoas entram com uma gripe e saem com uma infecção grave. Mandar mais gente para lá não cura a gripe. Um presídio superlotado e dominado por facção é esse hospital: quem entra por pouco sai mais preso ao crime.', crianca='Se um grupo de valentões manda na quadra e todo mundo que chega precisa entrar no grupo para não apanhar, colocar mais crianças na quadra só aumenta o grupo. Para acabar com isso, os adultos precisam voltar a cuidar da quadra.'),
 'milicias': dict(analogia='Contratar um segurança para a rua e descobrir que ele mesmo é quem assalta as casas de quem não paga, e que ele tem a chave da delegacia. A milícia é o segurança que virou dono do bairro, com a farda de quem deveria proteger.', crianca='Imagine que os monitores do recreio começam a cobrar lanche de todo mundo para deixar brincar, e quem reclama fica de castigo. O pior é que eles eram quem deveria cuidar das crianças. É por isso que alguém de fora precisa fiscalizar quem fiscaliza.'),
 'desigualdade-social': dict(analogia='Uma corrida em que alguns largam com tênis, água e treinador, e outros descalços, cem metros atrás. Dá para elogiar quem chegou primeiro, mas a corrida mede mais a largada do que as pernas. Reduzir a desigualdade é aproximar as largadas, para que a corrida meça o esforço.', crianca='Se numa turma alguns têm lanche todo dia e outros quase nunca, é difícil todo mundo prestar atenção na aula do mesmo jeito. Ajudar quem tem menos não é tirar de quem tem mais por maldade: é para todo mundo poder aprender e brincar junto.'),
 'bets': dict(analogia='Um parque de diversões que coloca máquinas de moeda em cada esquina, com luzes que piscam a cada quase vitória e um ídolo do seu time dizendo que você vai ganhar. A máquina não é desonesta: ela é feita para que você volte. O problema é quando quem volta é quem menos pode perder.', crianca='Tem jogos no celular que fazem você querer jogar sem parar e prometem prêmios. Quando envolve dinheiro de verdade, quase sempre quem ganha é a empresa do jogo. Por isso crianças não podem apostar, e adultos precisam tomar muito cuidado.'),
}

DID_BR = {
 'dividas-e-devedores': dict(obj=['Explicar para que servem a recuperação judicial, o Refis, o limite de cinco anos no cadastro e a lei do superendividamento', 'Distinguir o devedor por necessidade do devedor estratégico', 'Entender por que o calote de uns entra no juro de todos'], guardar=['Toda regra de alívio de dívida tem uma razão e um risco: proteger quem precisa ou premiar quem escolheu não pagar.', 'Sair do Serasa após cinco anos não apaga a dívida; só impede que ela seja usada para negar crédito.', 'Perdão genérico e recorrente estimula o atraso; alívio caso a caso, com cobrança firme de quem pode pagar, corrige isso.'], pensar='Pense em alguém que você conhece que se endividou. Foi necessidade ou escolha? Que regra seria justa para essa pessoa, e para quem empresta?', pre=['economia-para-entender-politica', 'o-que-esta-por-tras']),
 'impunidade': dict(obj=['Explicar por que o Brasil prende muito e, ainda assim, deixa a maioria dos homicídios sem culpado', 'Conhecer o que a lei diz sobre trânsito, menores e violência doméstica, separando fato de mito', 'Saber por que a certeza da punição pesa mais do que o tamanho da pena'], guardar=['O Brasil prende muito e mal: muitos presos por crimes menores, poucos homicídios esclarecidos.', 'Menores podem ser internados já na primeira vez quando há violência; o debate real é o tempo máximo e a idade.', 'Investigar bem reduz mais o crime do que aumentar penas que não se cumprem.'], pensar='Pense no último crime que você soube no seu bairro. Alguém foi identificado? O que faltou: lei, polícia, investigação ou Justiça?', pre=['corrupcao', 'politicas-baseadas-em-evidencias']),
 'os-protegidos': dict(obj=['Identificar as proteções de quem tem dinheiro, cargo e farda: recursos, prescrição, foro, imunidade, justiça militar e anistia', 'Separar proteções com razão de ser das que viraram privilégio', 'Conhecer as exceções recentes e o que mudaria o quadro'], guardar=['Para quem pode pagar, o tempo é a melhor defesa: recursos sucessivos e prescrição.', 'Foro e imunidade protegem o cargo de perseguição e viram escudo quando o poder protege os seus; a PEC da Blindagem foi barrada no Senado em 2025.', 'A punição de poderosos é possível, como mostram condenações recentes, e depende de instituições independentes e de pressão pública.'], pensar='Qual destas proteções você manteria, e qual mudaria: foro, imunidade, justiça militar, aposentadoria compulsória de juízes? Por quê?', pre=['impunidade', 'poder-paralelo']),
 'golpes-e-fraudes': dict(obj=['Reconhecer os golpes mais comuns e a técnica que todos usam: urgência e confiança', 'Entender por que o rastreamento e o bloqueio falham, e o que o MED faz', 'Saber quem responde pelo prejuízo e o que funcionaria melhor'], guardar=['O golpe virou o crime mais comum do país; quase 2 milhões de estelionatos por ano.', 'O dinheiro corre mais rápido que a investigação; o MED ampliado tenta seguir o valor por várias contas.', 'Banco não pede transferência: desligue e ligue você para o número oficial.'], pensar='Alguém da sua família já caiu ou quase caiu em um golpe? Que sinal teria evitado? Você já combinou com eles uma regra de checagem?', pre=['checagem-de-fatos']),
 'transparencia-dos-gastos': dict(obj=['Conhecer as ferramentas de transparência: LRF, Portal da Transparência, LAI e tribunais de contas', 'Identificar o que ainda se esconde: sigilos, orçamento secreto, emendas Pix e penduricalhos', 'Saber fiscalizar um gasto perto de você'], guardar=['A regra é o público; o sigilo é exceção, justificada e com prazo.', 'O orçamento secreto foi declarado inconstitucional em 2022; as emendas Pix seguem difíceis de rastrear.', 'Qualquer pessoa pode pedir informação pela Lei de Acesso, sem justificar.'], pensar='Escolha um gasto perto de você, como a merenda da escola ou uma obra da cidade. Você sabe onde encontrar quanto custou? Tente esta semana.', pre=['politicas-publicas', 'corrupcao']),
 'faccoes-e-sistema-prisional': dict(obj=['Contar como PCC e Comando Vermelho nasceram nos presídios e se espalharam', 'Explicar por que a prisão superlotada recruta para a facção', 'Comparar confronto, inteligência financeira, controle das prisões e presença do Estado'], guardar=['As maiores facções nasceram dentro das prisões, e a prisão superlotada continua sendo seu centro de recrutamento.', 'Prender varejistas pequenos não reduz o tráfico; asfixiar o dinheiro e retomar os presídios desorganiza mais.', 'Grandes operações letais raramente mudam o controle do território por muito tempo.'], pensar='Se você morasse numa área dominada por facção, o que mais faria diferença na sua vida: uma operação policial, uma escola integral, ou poder confiar na polícia? Por quê?', pre=['impunidade', 'poder-paralelo']),
 'milicias': dict(obj=['Explicar o que são milícias e como controlam território, serviços e votos', 'Entender a relação entre milícia, polícia e política, com o caso Marielle', 'Distinguir a polícia honesta da milícia e saber o que funciona contra ela'], guardar=['A milícia é crime organizado de dentro do Estado: agentes que usam a farda para explorar o território.', 'Território controlado vira voto, e voto vira proteção; por isso a milícia é um problema da democracia.', 'O combate passa por seguir o dinheiro, regularizar serviços e ter controle externo forte sobre a polícia.'], pensar='Que serviços do seu bairro são clandestinos (gás, internet, transporte, terreno)? Quem os controla? O que aconteceria se o Estado os regularizasse?', pre=['faccoes-e-sistema-prisional', 'poder-paralelo']),
 'desigualdade-social': dict(obj=['Conhecer o tamanho da desigualdade brasileira e como ela se mede', 'Identificar as causas históricas e atuais: escravidão, educação, trabalho, impostos e discriminação', 'Saber o que os dados mostram sobre o que reduziu a desigualdade e onde está a disputa'], guardar=['O Brasil está entre os mais desiguais do mundo: os 10% mais ricos ficam com mais da metade da renda.', 'A desigualdade tem raízes históricas e é mantida por educação, informalidade, impostos regressivos e discriminação.', 'Salário mínimo valorizado, transferências focalizadas, educação e formalização reduziram a desigualdade; a disputa é sobre os meios.'], pensar='Pense em duas crianças nascidas no mesmo dia na sua cidade, uma no bairro mais rico e outra no mais pobre. O que deveria ser igual entre elas, e o que é aceitável ser diferente?', pre=['teorias-da-justica', 'economia-para-entender-politica']),
 'bets': dict(obj=['Contar como as bets foram legalizadas e reguladas no Brasil', 'Conhecer os dados sobre gasto, vício, dívida e manipulação', 'Comparar proibir, regular forte e regular leve'], guardar=['As bets foram legalizadas em 2018 e reguladas a partir de 2025; os brasileiros enviam bilhões por mês a elas.', 'O lucro vem sobretudo de uma minoria que aposta e perde muito; o produto é desenhado para manter o jogador.', 'A evidência favorece regulação forte: limites, pausa, autoexclusão e restrição de publicidade.'], pensar='Você conhece alguém que aposta? Quanto essa pessoa ganhou e perdeu no último mês? Ela saberia dizer?', pre=['vieses-cognitivos']),
}

